const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Get Alabama geometry from US Census data
  const states = ee.FeatureCollection('TIGER/2018/States');
  const alabama = states.filter(ee.Filter.eq('NAME', 'Alabama'));

  // Define time periods: full years 2003 and 2012
  const start2003 = '2003-01-01';
  const end2003 = '2003-12-31';
  const start2012 = '2012-01-01';
  const end2012 = '2012-12-31';

  // 2. Data Acquisition - Using GRACE Mascon product for water storage
  const grace2003 = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/MASCON')
    .filterDate(start2003, end2003)
    .select('lwe_thickness');  // Liquid water equivalent thickness (anomaly)

  const grace2012 = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/MASCON')
    .filterDate(start2012, end2012)
    .select('lwe_thickness');

  // Check for empty collections
  const count2003 = grace2003.size().getInfo();
  const count2012 = grace2012.size().getInfo();

  console.log(`2003 Images: ${count2003}`);
  console.log(`2012 Images: ${count2012}`);

  if (count2003 === 0 || count2012 === 0) {
    console.log(`<answer>C1</answer>`);
    return;
  }

  // Compute annual mean images
  const mean2003 = grace2003.mean();
  const mean2012 = grace2012.mean();

  // 3. Check for valid pixels
  const scale = 50000; // GRACE resolution is about 300km, using 50km scale

  const countStats2003 = mean2003.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: alabama,
    scale: scale,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  const countStats2012 = mean2012.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: alabama,
    scale: scale,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  console.log(`2003 Valid Pixels: ${countStats2003}`);
  console.log(`2012 Valid Pixels: ${countStats2012}`);

  if (countStats2003 === 0 || countStats2012 === 0) {
    console.log(`<answer>C2</answer>`);
    return;
  }

  // 4. Calculation - Get mean water storage anomaly for each year
  const meanVal2003 = mean2003.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: alabama,
    scale: scale,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  const meanVal2012 = mean2012.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: alabama,
    scale: scale,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  console.log(`2003 Mean Water Storage Anomaly: ${meanVal2003 ? meanVal2003.toFixed(4) : 'null'} m`);
  console.log(`2012 Mean Water Storage Anomaly: ${meanVal2012 ? meanVal2012.toFixed(4) : 'null'} m`);

  // 5. Validation & Final Answer
  if (meanVal2003 === null || meanVal2012 === null || 
      !isFinite(meanVal2003) || !isFinite(meanVal2012)) {
    console.log(`<answer>C3</answer>`);
    return;
  }

  // Check if water storage decreased (2012 < 2003)
  // Since these are anomalies in meters of water equivalent, negative means below baseline
  const change = meanVal2012 - meanVal2003;
  console.log(`Change (2012-2003): ${change.toFixed(4)} m`);

  if (meanVal2012 < meanVal2003) {
    console.log(`<answer>A</answer>`);
  } else {
    console.log(`<answer>B</answer>`);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
